-- Ficha de Manuel Troncoso.
--
-- La biografía de relleno lo describía en términos genéricos de merengue y música tropical,
-- sin mencionar que fue abogado y letrista, ni la disputa de autoría de «Por Amor».
-- primary_role de singer a composer; primary_genre de merengue a bolero; date_of_birth
-- corregida de 1927-09-27 a 1927-09-21; birth_place/province y second_last_name añadidos.

UPDATE artists SET primary_role = 'composer', primary_genre = 'bolero',
       date_of_birth = '1927-09-21', birth_place = 'Santo Domingo',
       province = 'Distrito Nacional', second_last_name = 'Ramírez'
       WHERE slug = 'manuel-troncoso';

